import { useState, useEffect } from "react";
import api from "../api";
import jsPDF from "jspdf";

function MealPlanPage() {
  const [families, setFamilies] = useState([]);
  const [selectedFamily, setSelectedFamily] = useState(null);
  const [dates, setDates] = useState([new Date().toISOString().split('T')[0]]);
  const [currentDateInput, setCurrentDateInput] = useState("");
  const [selectedMeals, setSelectedMeals] = useState(["Breakfast", "Lunch", "Dinner"]);
  const [plans, setPlans] = useState([]);
  const [upcomingGroceries, setUpcomingGroceries] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const MEAL_TYPES = ["Breakfast", "Lunch", "Dinner", "Snacks"];

  useEffect(() => {
    loadFamilies();
  }, []);

  useEffect(() => {
    if (selectedFamily) {
      loadUpcomingPlans();
    }
  }, [selectedFamily]);

  const loadFamilies = async () => {
    try {
      const res = await api.get("/families/");
      setFamilies(res.data);
      if (res.data && res.data.length > 0) {
        setSelectedFamily(res.data[0].id);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const loadUpcomingPlans = async () => {
    if (!selectedFamily) return;
    setLoading(true);
    try {
      const res = await api.get(`/families/${selectedFamily}/upcoming-plans`);
      setPlans(res.data.plans || []);
      setUpcomingGroceries(res.data.groceries || []);
    } catch (err) {
      console.error(err);
    }
    setLoading(false);
  };

  const toggleMeal = (meal) => {
    setSelectedMeals(prev => 
      prev.includes(meal) ? prev.filter(m => m !== meal) : [...prev, meal]
    );
  };

  const addDate = () => {
    if (currentDateInput && !dates.includes(currentDateInput)) {
      setDates([...dates, currentDateInput].sort());
      setCurrentDateInput("");
    }
  };

  const removeDate = (dateToRemove) => {
    setDates(dates.filter(d => d !== dateToRemove));
  };

  const generateAndLoadPlan = async () => {
    if (!selectedFamily) return;
    if (selectedMeals.length === 0) {
      setError("Please select at least one meal to generate.");
      return;
    }
    if (dates.length === 0) {
      setError("Please select at least one date.");
      return;
    }
    
    setLoading(true);
    setError("");
    try {
      await api.post(`/families/${selectedFamily}/multi-daily-plan`, {
        dates,
        meals: selectedMeals
      });
      // reload all upcoming after generating
      loadUpcomingPlans();
    } catch (err) {
      console.error(err);
      setError("Failed to load or generate plan. Please try again.");
      setLoading(false);
    }
  };

  const downloadPDF = (groceryText, datesArr) => {
    const doc = new jsPDF();
    
    doc.setFont("helvetica", "bold");
    doc.setFontSize(22);
    doc.setTextColor("#10b981");
    doc.text("NutriGen AI - Grocery List", 20, 20);
    
    doc.setFontSize(12);
    doc.setTextColor("#64748b");
    doc.text(`Dates: ${datesArr.join(", ")}`, 20, 30);
    
    doc.setLineWidth(0.5);
    doc.line(20, 35, 190, 35);

    doc.setFont("helvetica", "normal");
    doc.setTextColor("#000000");
    
    // Split text so it wraps properly
    const lines = doc.splitTextToSize(groceryText, 170);
    doc.text(lines, 20, 45);

    doc.save(`Grocery_List_${datesArr[0]}.pdf`);
  };

  // Group plans by date for rendering
  const groupedPlans = plans.reduce((acc, plan) => {
    if (!acc[plan.date]) acc[plan.date] = [];
    acc[plan.date].push(plan);
    return acc;
  }, {});

  return (
    <div className="page anim-fade-in">
      <h1 style={{ color: "#38bdf8", textShadow: "0 0 10px rgba(56,189,248,0.3)" }}>
        Multi-Day Meal & Grocery Planner
      </h1>
      
      <div className="card" style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <div style={{ display: 'flex', gap: '20px', alignItems: 'center', flexWrap: 'wrap' }}>
          {families.length > 0 && (
            <select 
              value={selectedFamily || ""} 
              onChange={e => setSelectedFamily(e.target.value)}
              className="date-picker"
              style={{ padding: "12px", borderRadius: "8px" }}
            >
              {families.map(f => (
                <option key={f.id} value={f.id}>{f.name}</option>
              ))}
            </select>
          )}

          <div style={{ display: 'flex', gap: '10px' }}>
            <input 
              type="date" 
              className="date-picker"
              value={currentDateInput}
              onChange={(e) => setCurrentDateInput(e.target.value)}
            />
            <button onClick={addDate} style={{ marginTop: '0', background: '#10b981' }}>Add Date</button>
          </div>
        </div>

        <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
          {dates.map(d => (
            <div key={d} style={{ background: '#334155', padding: '5px 12px', borderRadius: '15px', color: '#fff', display: 'flex', alignItems: 'center', gap: '8px' }}>
              {d} <span style={{ cursor: 'pointer', color: '#ef4444', fontWeight: 'bold' }} onClick={() => removeDate(d)}>×</span>
            </div>
          ))}
        </div>

        <div>
          <h3 style={{ margin: "10px 0", color: "#94a3b8" }}>Select Required Meals:</h3>
          <div className="meal-bar-container">
            {MEAL_TYPES.map(meal => (
              <button 
                key={meal}
                className={`meal-btn ${selectedMeals.includes(meal) ? 'active' : ''}`}
                onClick={() => toggleMeal(meal)}
              >
                {meal}
              </button>
            ))}
          </div>
        </div>

        <button 
          onClick={generateAndLoadPlan} 
          disabled={loading}
          style={{ 
            alignSelf: 'flex-start', 
            background: loading ? "#475569" : "#0ea5e9",
            fontWeight: "bold",
            padding: "12px 24px"
          }}
        >
          {loading ? "Processing..." : "Generate Missing / Reload"}
        </button>
      </div>

      {error && <p style={{ color: "#ef4444" }}>{error}</p>}

      <h2 style={{marginTop: "30px", paddingBottom: "10px", borderBottom: "1px solid #334155"}}>📅 Scheduled Active Plans</h2>

      {plans.length > 0 && !loading && (
        <div className="anim-fade-in">
          {Object.entries(groupedPlans).map(([date, datePlans]) => (
            <div key={date} style={{ marginBottom: "30px" }}>
              <h2 style={{ color: "#fff", borderBottom: "2px solid #38bdf8", paddingBottom: "10px" }}>{date}</h2>
              <div className="grid">
                {datePlans.map((plan, idx) => (
                  <div key={idx} className="card daily-plan-card">
                    <h3 className="meal-type-title">{plan.meal_type}</h3>
                    <div className="pre">{plan.plan_text}</div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {upcomingGroceries.map((groc, i) => (
        <div key={i} className="card anim-fade-in" style={{ marginTop: '20px', borderTop: '4px solid #10b981', position: 'relative' }}>
          <h2 style={{ color: '#10b981' }}>🛒 Combined Grocery List (Dates: {groc.dates.join(', ')})</h2>
          <button 
            onClick={() => downloadPDF(groc.grocery_list, groc.dates)}
            style={{ position: 'absolute', top: '15px', right: '15px', background: '#ef4444', padding: '8px 16px' }}
          >
            Download PDF
          </button>
          <div className="pre" style={{ background: '#0f172a', padding: '15px', borderRadius: '8px', color: '#94a3b8', marginTop: '10px' }}>
            {groc.grocery_list}
          </div>
        </div>
      ))}

      {plans.length === 0 && !loading && !error && (
        <div style={{ textAlign: "center", marginTop: "40px", color: "#64748b" }}>
          <h3>No plans currently active.</h3>
          <p>Add dates, select meals, and hit generate to schedule your plan!</p>
        </div>
      )}
    </div>
  );
}

export default MealPlanPage;
